const CFG=window.RADAR_CONFIG||{};
const CLOUD=!!(CFG.supabaseUrl&&CFG.supabaseAnonKey&&window.supabase&&window.supabase.createClient);
const sb=CLOUD?window.supabase.createClient(CFG.supabaseUrl,CFG.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,lock:(n,t,fn)=>fn()}}):null;
let senhaTmp='',pendente=false;
function traduz(m){m=String(m||'');if(/already registered|already been registered/i.test(m))return 'Este e-mail já tem conta. Entre pelo login.';if(/rate limit|too many/i.test(m))return 'Muitas tentativas. Aguarde um minuto e tente de novo.';if(/Invalid login/i.test(m))return 'E-mail ou senha incorretos.';if(/Email not confirmed/i.test(m))return 'Confirme seu e-mail com o código antes de entrar.';if(/expired|invalid/i.test(m))return 'Código incorreto ou expirado.';if(/duplicate key|23505/i.test(m))return 'Este CPF, CNPJ ou concorrente já está cadastrado.';if(/Limite de concorrentes/i.test(m))return 'Você atingiu o limite de concorrentes do seu plano.';if(/Failed to fetch|NetworkError/i.test(m))return 'Sem conexão com o servidor. Verifique a internet.';return m}
const concFromDB=r=>({id:r.id,nome:r.nome,ig:r.instagram,fb:r.facebook||'',site:r.site||'',cidade:r.cidade||'',criado:Date.parse(r.criado_em),check:Date.parse(r.ultima_verificacao)});
function limparSessao(){try{Object.keys(localStorage).filter(k=>/^sb-.*-auth-token/.test(k)).forEach(k=>localStorage.removeItem(k))}catch(e){}}
const comPrazo=(pr,ms)=>Promise.race([pr,new Promise((_,r)=>setTimeout(()=>r(new Error('tempo esgotado')),ms))]);
async function carregar(){const {data:u,error:ue}=await comPrazo(sb.auth.getUser(),8000);const user=u&&u.user;if(!user){if(ue)limparSessao();return false}
 const [p,e,c,v]=await Promise.all([sb.from('perfis').select('*').eq('id',user.id).maybeSingle(),sb.from('empresas').select('*').eq('user_id',user.id).maybeSingle(),sb.from('concorrentes').select('*').order('criado_em',{ascending:false}),sb.from('verificacoes').select('concorrente_id,feita_em,dados').order('feita_em',{ascending:false}).limit(300)]);
 if(!p.data||!e.data){pendente=true;return 'incompleto'}
 const P=p.data,E=e.data;
 conta={resp:{nome:P.nome,cpf:P.cpf,nasc:P.nascimento,tel:P.telefone,email:P.email},emp:{cnpj:E.cnpj,razao:E.razao_social,fantasia:E.nome_fantasia,seg:E.segmento,tel:E.telefone||'',cep:E.cep||'',num:E.numero||'',rua:E.endereco||'',bairro:E.bairro||'',cidade:E.cidade||''},loja:{ig:E.instagram,fb:E.facebook,site:E.site||'',seg:E.seguidores||0,meta:E.meta_seguidores||0,desc:E.descricao||'',logo:E.logo||''},criado:Date.parse(E.criado_em)};
 const ult={};(v&&v.data||[]).forEach(x=>{if(!ult[x.concorrente_id])ult[x.concorrente_id]=x});
 conc=(c.data||[]).map(r=>{const o=concFromDB(r),x=ult[r.id];if(x){o.v=x.dados;o.vEm=Date.parse(x.feita_em)}return o});await carregaPlano();sess=true;return true}
async function verificarNuvem(id){try{const {data,error}=await sb.functions.invoke('verificar',{body:{concorrente_id:id}});
 if(error){let m=error.message;try{const j=await error.context.json();if(j&&j.erro)m=j.erro}catch(_){}return {erro:/Failed to send|fetch/i.test(m)?'O robô ainda não foi instalado no Supabase.':m}}
 const c=conc.find(x=>x.id===id);if(c&&data&&data.dados){c.v=data.dados;c.vEm=c.check=Date.parse(data.feita_em)}return data||{}}catch(e){return {erro:e.message}}}
async function emailConfirmado(){try{let {data}=await sb.auth.getUser();let u=data&&data.user;
 if((!u||!u.email_confirmed_at)&&senhaTmp&&draft.resp&&draft.resp.email){const r=await sb.auth.signInWithPassword({email:draft.resp.email,password:senhaTmp});u=r.data&&r.data.user}
 return !!(u&&u.email_confirmed_at&&draft.resp&&u.email===draft.resp.email)}catch(e){return false}}
async function marcarConfirmado(){if(pendente||!CLOUD)return;if(await emailConfirmado()){pendente=true;const o=$('okMail');if(o)o.hidden=false;const c=document.querySelector('.code');if(c)c.style.opacity=.35;const m=$('codeMsg');if(m)m.textContent=''}}
async function enviarCodigo(){if(pendente)return true;if(!senhaTmp){toast('Por segurança, volte ao passo 1 e digite a senha de novo.');return false}
 const {data:su,error}=await sb.auth.signUp({email:draft.resp.email,password:senhaTmp,options:{data:{nome:draft.resp.nome},emailRedirectTo:location.href.split('#')[0]}});
 if(error){toast(traduz(error.message));return false}
 if(su&&su.user&&Array.isArray(su.user.identities)&&su.user.identities.length===0){toast('Este e-mail já tem cadastro. Entre pelo login para continuar.');setTimeout(()=>go('entrar'),1200);return false}return true}
async function salvarConta(){const {data:u}=await sb.auth.getUser();const uid=u&&u.user&&u.user.id;if(!uid){toast('Sessão expirada. Entre de novo.');return false}
 const r=draft.resp,e=draft.emp,l=draft.loja;
 let q=await sb.from('perfis').upsert({id:uid,nome:r.nome,cpf:r.cpf,nascimento:r.nasc,telefone:r.tel,email:r.email});if(q.error){toast(traduz(q.error.message));return false}
 q=await sb.from('empresas').upsert({user_id:uid,cnpj:e.cnpj,razao_social:e.razao,nome_fantasia:e.fantasia,segmento:e.seg,telefone:e.tel,cep:e.cep,endereco:e.rua,numero:e.num,bairro:e.bairro,cidade:e.cidade,instagram:l.ig,facebook:l.fb,site:l.site,seguidores:l.seg,meta_seguidores:l.meta,descricao:l.desc,logo:l.logo||null},{onConflict:'user_id'});if(q.error){toast(traduz(q.error.message));return false}
 return true}
async function nuvem(acao,c){if(!CLOUD)return true;let q;
 if(acao==='novo'){q=await sb.from('concorrentes').insert({nome:c.nome,instagram:c.ig,facebook:c.fb||null,site:c.site||null,cidade:c.cidade||null,ultima_verificacao:new Date(c.check).toISOString()}).select().single();if(!q.error){c.id=q.data.id;c.criado=Date.parse(q.data.criado_em)}}
 if(acao==='editar')q=await sb.from('concorrentes').update({nome:c.nome,instagram:c.ig,facebook:c.fb||null,site:c.site||null,cidade:c.cidade||null}).eq('id',c.id);
 if(acao==='check')q=await sb.from('concorrentes').update({ultima_verificacao:new Date(c.check).toISOString()}).eq('id',c.id);
 if(acao==='apagar')q=await sb.from('concorrentes').delete().eq('id',c.id);
 if(q&&q.error){toast(traduz(q.error.message));return false}return true}
function toast(m){$('toast').textContent=m;$('toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').hidden=true,2600)}

